164:                         Powered by Stripe (Test Mode)
165:                     </div>
166:                 </div>
167: 
168:                 {/* Visual Card Preview */}
169:                 <div className={`relative w-full max-w-md mx-auto h-48 rounded-2xl bg-gradient-to-br ${methodData.color} p-6 mb-8 shadow-2xl overflow-hidden`}>
170:                     {/* Background pattern */}
171:                     <div className="absolute inset-0 opacity-10">
172:                         <div className="absolute top-4 right-4 w-32 h-32 rounded-full border-2 border-white" />
173:                         <div className="absolute top-8 right-8 w-24 h-24 rounded-full border-2 border-white" />
174:                         <div className="absolute -bottom-8 -left-8 w-40 h-40 rounded-full border-2 border-white" />
175:                     </div>
176: 
177:                     {/* Chip */}
178:                     <div className="relative">
179:                         <div className="w-12 h-9 bg-gradient-to-br from-yellow-300 to-yellow-500 rounded-lg mb-6 flex items-center justify-center">
180:                             <div className="w-8 h-5 border border-yellow-600/30 rounded-sm" />
181:                         </div>
182: 
183:                         <p className="text-white text-xl font-mono tracking-[0.2em] mb-6">
184:                             ΓÇóΓÇóΓÇóΓÇó ΓÇóΓÇóΓÇóΓÇó ΓÇóΓÇóΓÇóΓÇó ΓÇóΓÇóΓÇóΓÇó
185:                         </p>
186: 
187:                         <div className="flex items-end justify-between">
188:                             <div>
189:                                 <p className="text-white/50 text-[10px] uppercase tracking-wider mb-0.5">Secure Payment</p>
190:                                 <p className="text-white font-bold text-sm uppercase tracking-wide">
191:                                     STRIPE TEST MODE
192:                                 </p>
193:                             </div>
194:                             <div className="text-right">
195:                                 <p className="text-white/50 text-[10px] uppercase tracking-wider mb-0.5">{methodData.name}</p>
196:                                 <p className="text-white font-bold text-sm font-mono">
197:                                     Γé╣{orderAmount ? orderAmount.toLocaleString('en-IN') : 'ΓÇö'}
198:                                 </p>
199:                             </div>
200:                         </div>
201:                     </div>
202:                 </div>
203: 
204:                 {/* Stripe Card Form */}
205:                 <form onSubmit={handleSubmit} className="bg-white rounded-2xl border border-gray-100 shadow-lg p-6 md:p-8 space-y-5">
206: 
207:                     {/* Stripe CardElement */}
208:                     <div>
209:                         <label className="block text-sm font-bold text-gray-700 mb-2">Card Details</label>
210:                         <div className={`px-4 py-4 border-2 rounded-xl transition-all ${cardError ? 'border-red-400 bg-red-50' : 'border-gray-200 focus-within:border-primary-500 focus-within:ring-2 focus-within:ring-primary-100'}`}>
211:                             <CardElement
212:                                 options={CARD_ELEMENT_OPTIONS}
213:                                 onChange={(e) => {
214:                                     setCardComplete(e.complete);
215:                                     setCardError(e.error ? e.error.message : '');
216:                                 }}
217:                             />
218:                         </div>
219:                         {cardError && <p className="text-xs text-red-500 mt-1.5 font-medium">{cardError}</p>}
220:                         <p className="text-xs text-gray-400 mt-2">
221:                             Test card: <span className="font-mono font-bold text-gray-500">4242 4242 4242 4242</span> ΓÇó Any future date ΓÇó Any CVC
222:                         </p>
223:                     </div>
224: 
225:                     {/* Security note */}
226:                     <div className="flex items-center gap-2 bg-green-50 border border-green-200 rounded-xl px-4 py-3">
227:                         <FiShield className="text-green-500 flex-shrink-0" size={16} />
228:                         <p className="text-xs text-green-700 font-medium">
229:                             Your card details are handled securely by Stripe. We never see your full card number.
230:                         </p>
231:                     </div>
232: 
233:                     {/* Pay Button */}
234:                     <button
235:                         type="submit"
236:                         disabled={!stripe || !cardComplete || processing}
237:                         className={`w-full py-4 rounded-xl font-black text-white text-lg transition-all flex items-center justify-center gap-3 shadow-lg active:scale-[0.98] ${
238:                             !stripe || !cardComplete || processing
239:                                 ? 'bg-gray-300 cursor-not-allowed shadow-none'
240:                                 : `bg-gradient-to-r ${methodData.color} hover:shadow-xl`
241:                         }`}
242:                     >
243:                         {processing ? (
244:                             <>
245:                                 <svg className="animate-spin h-5 w-5 text-white" viewBox="0 0 24 24" fill="none">
246:                                     <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
247:                                     <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
248:                                 </svg>
249:                                 Processing PaymentΓÇª
250:                             </>
251:                         ) : (
252:                             <>
253:                                 <FiLock size={18} />
254:                                 Pay Γé╣{orderAmount ? orderAmount.toLocaleString('en-IN') : 'ΓÇö'}
255:                             </>
256:                         )}
257:                     </button>
258:                 </form>
259: 
260:                 {/* Security Footer */}
261:                 <div className="mt-6 flex items-center justify-center gap-6">
262:                     <div className="flex items-center gap-1.5 text-xs text-gray-400">
263:                         <FiShield className="text-green-400" size={14}/>
264:                         <span>256-bit SSL</span>
265:                     </div>
266:                     <div className="w-px h-4 bg-gray-200" />
267:                     <div className="flex items-center gap-1.5 text-xs text-gray-400">
268:                         <FiLock className="text-green-400" size={14}/>
269:                         <span>PCI DSS Compliant</span>
270:                     </div>
271:                     <div className="w-px h-4 bg-gray-200" />
272:                     <div className="flex items-center gap-1.5 text-xs text-gray-400">
273:                         <FiShield className="text-green-400" size={14}/>
274:                         <span>Stripe Secured</span>
275:                     </div>
276:                 </div>
277:             </div>
278:         </div>
279:     );
